select mn.*, rwi.* from Outline_Lib_Risk mn left join risk_warn_index rwi on rwi.rwi_id = mn.Risk_Id where osl_id in
#{item}
order by mn.Olr_Sort

select
mn.*,
rwi.*
from Outline_Lib_Risk mn
left join risk_warn_index rwi on rwi.rwi_id = mn.Risk_Id

    
        mn.osl_id = #{params.oslId}
    
    
        and mn.risk_id = #{params.riskId}
    
    
        and mn.create_uid=#{params.createUname}
    
    
        and INSTR(mn.create_uname,#{params.createUname})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
